/** The tag of the string annotation that marks a file name inside a text (D100 (6), D101 (6)); see sbFileName. */
internal const val SB_FILE_NAME = "sb-file-name"

/** A zero-width space: a place to break without a glyph and without a hyphen. */
private const val SB_ZWSP = '\u200B'

/**
 * A file name marked for the wrappers („export-2026-10-10.csv“; D100 (6), D101 (6)): in SbCallout and SbMetaList it
 * breaks only after - . _ / and without a hyphen, and only a part that alone is wider than the line breaks inside
 * itself. Build the text with it: `buildAnnotatedString { append("Gesichert als "); append(sbFileName(name));
 * append(".") }`. Identifiers („DAT-02“, „1.4.0“) stay plain text and never break inside (D80). TalkBack reads the
 * name as written, by character and by word as well (D100 (7)). Inside an app's SelectionContainer a copied name
 * keeps the zero-width spaces the wrapper draws (§16, a known limit).
 */
fun sbFileName(name: String): AnnotatedString = buildAnnotatedString {
    pushStringAnnotation(SB_FILE_NAME, name)
    append(name)
    pop()
}

/**
 * The index of the dot before a file name's extension of one to four letters or digits („.csv“, „.md“, „.mp3“) in
 * [name], else -1: no break goes there, so the extension stays with the last part (§16, 2026-10-26; provisional,
 * agent).
 */
private fun sbExtensionDot(name: CharSequence): Int {
    val dot = name.lastIndexOf('.')
    if (dot <= 0) return -1
    val ext = name.length - dot - 1
    return if (ext in 1..4 && (dot + 1 until name.length).all { name[it].isLetterOrDigit() }) dot else -1
}

/**
 * Whether [name] may break after its character at [i] (D100 (6), D101 (6)): after - . _ /, not after its last
 * character, not after the dot of a short extension ([dot], §16), not inside a run of separators („a//b“ breaks
 * after „//“ only) and not after the separators the name begins with („/Users/x“ never breaks after its first „/“,
 * „../a“ never after „../“; 2026-10-27, provisional, agent).
 */
private fun sbBreaksAfter(name: CharSequence, i: Int, dot: Int): Boolean {
    if (name[i] !in "-._/" || i >= name.length - 1 || i == dot) return false
    if (name[i + 1] in "-._/") return false
    return (0 until i).any { name[it] !in "-._/" }
}

/** A file name's parts as it may break: each ends after - . _ /, the extension stays with the part before it. */
private fun sbFileNameParts(name: String): List<String> {
    val dot = sbExtensionDot(name)
    val parts = mutableListOf<String>()
    var from = 0
    for (i in name.indices) {
        if (sbBreaksAfter(name, i, dot)) {
            parts += name.substring(from, i + 1)
            from = i + 1
        }
    }
    if (from < name.length) parts += name.substring(from)
    return parts
}

/**
 * [text] with a zero-width space after each - . _ / inside a marked file name (not after its last character, and not
 * after the dot of a short extension, §16): there Android's line breaker may break, without a hyphen, also before a
 * digit (D101 (6)). The same object when nothing is marked. Public since 2026-10-26 (§16) for an app's own text;
 * [SbFileNameText] also gives TalkBack the name without the marks.
 */
fun sbFileNameBreaks(text: AnnotatedString): AnnotatedString {
    val marks = text.getStringAnnotations(SB_FILE_NAME, 0, text.length).sortedBy { it.start }
    if (marks.isEmpty()) return text
    return buildAnnotatedString {
        var at = 0
        marks.forEach { mark ->
            if (mark.start < at) return@forEach
            append(text.subSequence(at, mark.start))
            val name = text.subSequence(mark.start, mark.end)
            val dot = sbExtensionDot(name)
            for (i in name.indices) {
                append(name.subSequence(i, i + 1))
                if (sbBreaksAfter(name, i, dot)) append(SB_ZWSP)
            }
            at = mark.end
        }
        append(text.subSequence(at, text.length))
    }
}

/** [text] with every marked file name blanked out: the words that may be hyphenated. */
private fun sbOutsideFileNames(text: AnnotatedString): String {
    val chars = text.text.toCharArray()
    text.getStringAnnotations(SB_FILE_NAME, 0, text.length).forEach { m -> for (i in m.start until m.end) chars[i] = ' ' }
    return String(chars)
}

/**
 * The widest word of [text] in [style], in px: what one line must hold so that [text] breaks only between words
 * (D99 (1)). A word ends at a space or after a hyphen before a letter („Werbe-ID“ may break after „Werbe-“, not
 * „2026-10“, as Android's line breaker); U+00A0 joins („60 %“).
 */
internal fun TextMeasurer.sbWidestWord(text: String, style: TextStyle): Int =
    text.split(' ', '\n', '\t')
        .flatMap { it.split(Regex("(?<=-)(?=\\p{L})")) }
        .filter { it.isNotEmpty() }
        .maxOfOrNull { measure(it, style, softWrap = false, maxLines = 1).size.width } ?: 0

/** As above, where a marked file name counts as its parts, each ending after - . _ / (D101 (6)). */
internal fun TextMeasurer.sbWidestWord(text: AnnotatedString, style: TextStyle): Int {
    val parts = text.getStringAnnotations(SB_FILE_NAME, 0, text.length)
        .flatMap { m -> sbFileNameParts(text.text.substring(m.start, m.end)) }
        .filter { it.isNotEmpty() }
    return maxOf(
        sbWidestWord(sbOutsideFileNames(text), style),
        parts.maxOfOrNull { measure(it, style, softWrap = false, maxLines = 1).size.width } ?: 0,
    )
}

/** [text] with its no-break spaces as ordinary spaces, of the same length; [text] itself when none opens. */
private fun sbOpenNoBreaks(text: AnnotatedString): AnnotatedString {
    val open = text.text.replace(SB_OPEN_NO_BREAK, " ")
    return if (open == text.text) text else AnnotatedString(open, text.spanStyles, text.paragraphStyles)
}

/** A no-break space, except before „…“: an ellipsis on a line of its own says nothing (CHECKS.md §85). */
private val SB_OPEN_NO_BREAK = Regex("[\\u00A0\\u202F](?!…)")

/**
 * [text] laid out with the lines of [drawn] (the same text with the break marks of sbFileNameBreaks): one paragraph
 * per drawn line, so TalkBack's reading by line gets the lines it sees at the offsets of the text as written.
 */
private fun TextMeasurer.sbSameLines(text: AnnotatedString, drawn: TextLayoutResult): TextLayoutResult {
    val marked = drawn.layoutInput.text.text
    fun at(i: Int) = i - (0 until i).count { marked[it] == SB_ZWSP }
    val lines = AnnotatedString.Builder(text)
    for (line in 0 until drawn.lineCount) {
        val from = at(drawn.getLineStart(line))
        val to = at(drawn.getLineEnd(line))
        if (to > from) lines.addStyle(ParagraphStyle(), from, to)
    }
    return measure(
        lines.toAnnotatedString(),
        drawn.layoutInput.style,
        constraints = drawn.layoutInput.constraints,
        layoutDirection = drawn.layoutInput.layoutDirection,
        density = drawn.layoutInput.density,
    )
}

/**
 * [SbWrapText] for a plain string: an app's own body text, caption or label that must never be cut (D99 (1), ZUG-09,
 * TXT-15), e.g. `SbWrapText(hint, SebaroTheme.typography.body, SebaroTheme.colors.textMuted)`. Public since
 * 2026-10-28 (Android template, A-T1); the signature is the one the wrappers always used.
 */
@Composable
fun SbWrapText(text: String, style: TextStyle, color: Color, modifier: Modifier = Modifier, center: Boolean = false) {
    SbWrapText(AnnotatedString(text), style, color, modifier, center)
}

/**
 * A file name or path on its own (§16, 2026-10-26; provisional, agent): [name] breaks only after - . _ /, never
 * before a short extension, without a hyphen, and a part wider than the line breaks inside (D101 (6), §16);
 * TalkBack reads it as written. [style] defaults to body; the caller passes its own (a list row's title, a caption).
 */
@Composable
fun SbFileNameText(
    name: String,
    modifier: Modifier = Modifier,
    style: TextStyle = SebaroTheme.typography.body,
    color: Color = SebaroTheme.colors.text,
) {
    SbWrapText(sbFileName(name), style, color, modifier)
}

/**
 * Text that wraps between words onto as many lines as its place allows and is never clipped or cut with an ellipsis
 * (D99 (1)). Only when a single word outside a file name is wider than the whole line is the text hyphenated
 * (Hyphens.Auto with the simple line break); a marked file name (sbFileName) breaks after - . _ / without a hyphen,
 * and a part of it that alone is too wide breaks inside (D101 (6)). [center] centres the lines of a text that wraps (a
 * one-line text is centred by its parent, so it draws as a plain Text would). A normal BasicText (D100 (7)): TalkBack
 * gets its text and its text layout, so it reads by character, word and line; heading, merging, baselines and
 * intrinsic sizes are the Text's. The style follows the width of the last layout, so the very first frame may still
 * lack a hyphen or the centring (accepted by D100 (7)); a file name is read as written, its lines measured on it.
 *
 * Apps use it for their own text where a plain Text would be cut or hyphenated at large text (§16): pass the type role
 * and colour from [SebaroTheme] ([style] and [color] have no defaults, so the role is always chosen), the width comes
 * from [modifier] or the parent. Not for a text field's value (it scrolls, D110, D111 (4)) or a one-line placeholder
 * (it may end in „…“, D111 (3)), and not for identifiers that never break („DAT-02“, „1.4.0“, D80).
 */
@Composable
fun SbWrapText(
    text: AnnotatedString,
    style: TextStyle,
    color: Color,
    modifier: Modifier = Modifier,
    center: Boolean = false,
) {
    val measurer = rememberTextMeasurer()
    val plain = style.copy(color = color)
    val shown = remember(text) { sbFileNameBreaks(text) }
    val widest = remember(text, plain, measurer) { measurer.sbWidestWord(sbOutsideFileNames(text), plain) }
    var width by remember(text, plain) { mutableIntStateOf(Constraints.Infinity) }
    var wraps by remember(text, plain) { mutableStateOf(false) }
    val drawn = remember { arrayOfNulls<TextLayoutResult>(1) }
    val misses = widest > width
    // CHECKS.md §80 (provisional, agent), D130 for every wrapping text: a word that misses only because of the dark
    // letter spacing (D44) drops that spacing instead of hyphenating
    val flat = remember(plain) { plain.copy(letterSpacing = 0.em) }
    val flatFits = remember(text, plain, measurer, misses, width) {
        misses && plain.letterSpacing != 0.em && measurer.sbWidestWord(sbOutsideFileNames(text), flat) <= width
    }
    // CHECKS.md §84 (provisional, agent): number and unit part at their no-break space before a word is hyphenated
    val opened = remember(text) { sbOpenNoBreaks(shown) }
    val openFits = remember(text, plain, measurer, misses, flatFits, width) {
        misses && !flatFits && opened !== shown && measurer.sbWidestWord(sbOutsideFileNames(sbOpenNoBreaks(text)), plain) <= width
    }
    val split = when {
        !misses || openFits -> plain
        flatFits -> flat
        else -> plain.copy(hyphens = Hyphens.Auto, lineBreak = LineBreak.Simple)
    }
    val laid = if (openFits) opened else shown
    BasicText(
        laid,
        modifier.then(
            if (laid === text) {
                Modifier
            } else {
                // TalkBack reads the text without the break marks, and its lines as they are drawn
                Modifier.semantics {
                    this[SemanticsProperties.Text] = listOf(text)
                    this[SemanticsActions.GetTextLayoutResult] = AccessibilityAction(null) { out ->
                        val last = drawn[0] ?: return@AccessibilityAction false
                        out.add(measurer.sbSameLines(text, last))
                        true
                    }
                }
            },
        ),
        style = if (center && wraps) split.copy(textAlign = TextAlign.Center) else split,
        onTextLayout = { r ->
            drawn[0] = r
            val w = r.layoutInput.constraints.maxWidth
            if (w != width) width = w
            if ((r.lineCount > 1) != wraps) wraps = r.lineCount > 1
        },
    )
}
